package com.ncdex.instrument.service;
import com.ncdex.instrument.document.Instrument; import com.ncdex.instrument.repository.InstrumentRepository; import org.springframework.data.redis.core.RedisTemplate; import org.springframework.stereotype.Service; import org.springframework.cache.annotation.*; import java.time.Duration; import java.util.*;
@Service public class InstrumentService {private final InstrumentRepository repo; private final RedisTemplate<String,Object> redis; private static final String PREFIX="instrument:"; public InstrumentService(InstrumentRepository r,RedisTemplate<String,Object> redis){this.repo=r;this.redis=redis;} public List<Instrument> all(){return repo.findAll();} public List<Instrument> search(String q){return repo.findByNameContainingIgnoreCaseOrSymbolContainingIgnoreCase(q,q);} public Instrument get(String id){String key=PREFIX+id;Object cached=redis.opsForValue().get(key);if(cached instanceof Instrument i)return i;Instrument i=repo.findById(id).orElseThrow(()->new NoSuchElementException("Instrument not found: "+id));redis.opsForValue().set(key,i,Duration.ofMinutes(5));return i;} public Instrument create(Instrument i){if(i.getId()==null||i.getId().isBlank())throw new IllegalArgumentException("Instrument id is required");if(repo.existsBySymbolIgnoreCase(i.getSymbol()))throw new IllegalArgumentException("Symbol already exists");return repo.save(i);} public Instrument update(String id,Instrument in){Instrument old=repo.findById(id).orElseThrow(()->new NoSuchElementException("Instrument not found: "+id));old.setName(in.getName());old.setSymbol(in.getSymbol());old.setCategory(in.getCategory());old.setIndicativePrice(in.getIndicativePrice());old.setActive(in.isActive());Instrument saved=repo.save(old);evict(id);return saved;} public Instrument setActive(String id,boolean active){Instrument i=repo.findById(id).orElseThrow(()->new NoSuchElementException("Instrument not found: "+id));i.setActive(active);Instrument saved=repo.save(i);evict(id);return saved;} public void evict(String id){redis.delete(PREFIX+id);} public void recordOrder(String id){repo.findById(id).ifPresent(i->{i.setOrderActivityCount(i.getOrderActivityCount()+1);repo.save(i);evict(id);});} }
